CREATE OR ALTER VIEW dbo.vw_prepaid_subscribers AS SELECT SubscriberID,SubscriberName,PhoneMasked,Balance,PlanID,ValidityEnd FROM dbo.Subscribers WHERE SubscriberType='Prepaid'; GO CREATE OR ALTER VIEW dbo.vw_recharge_summary AS SELECT s.SubscriberID,s.SubscriberName,COUNT(r.RechargeID) RechargeCount,COALESCE(SUM(r.Amount),0) TotalRecharged FROM dbo.Subscribers s LEFT JOIN dbo.RechargeHistory r ON r.SubscriberID=s.SubscriberID WHERE s.SubscriberType='Prepaid' GROUP BY s.SubscriberID,s.SubscriberName; GO SELECT * FROM dbo.vw_prepaid_subscribers; SELECT * FROM dbo.vw_recharge_summary;